public class Graph {

    private final Map<Integer,List<Edge>> adjacencyList;

    public Graph(){
       this.adjacencyList = new HashMap<>();
    }

    public void addEdge(int source,int destination,int weight){
       this.adjacencyList.computeIfAbsent(source,new ArrayList<>()).add(new Edge(source,destination,weight));
       this.adjacencyList.computeIfAbsent(destination,new ArrayList<>()).add(new Edge(destination,source,weight));
    }

    public List<Edge> getAdjacentNodes(int node){
       return this.adjacencyList.getOrDefault(node,new ArrayList<>());
    }


}
