class Node implements Comparable<Node>{
     private final Integer node;
     private Integer distanceFromSource;

     public Node(Integer node,Integer distanceFromSource){
         this.node=node;
         this.distanceFromSource=distanceFromSource;
     }


     @Override
     public boolean equals(Object o) {
         if (this == o) return true;
         if (!(o instanceof Node)) return false;

         Node node1 = (Node) o;

         return Objects.equals(node,node1.node);
     }


     @Override
     public String toString() {
         return "Node{" +
                 "node=" + node +
                 ", distanceFromSource=" + distanceFromSource +
                 '}';
     }


     @Override
     public int hashCode() {
         return Objects.hash(node);
     }


     @Override
     public int compareTo(Node otherNode) {
          if(this.distanceFromSource==otherNode.distanceFromSource)
              return Integer.compare(this.node.intValue(),otherNode.node.intValue());
          else
              return Integer.compare(this.distanceFromSource.intValue(),otherNode.distanceFromSource.intValue());
      }

