class Dijkstra{

    static List<Node> dijkstra(Graph graph,Integer source,Integer target){

       PriorityQueue<Node> priorityQueue=new PriorityQueue<>();
       Map<Integer,Integer> distances=new HashMap<>();

       for(Integer node : graph.adjacencyList.keySet()){
           distances.put(node,Integer.MAX_VALUE);
           priorityQueue.add(new Node(node,distances.get(node)));
       }

       distances.put(source,(int)0);

       while(!priorityQueue.isEmpty()){

           Node currentNode=priorityQueue.poll();

           if(currentNode.node.equals(target))
               break;


           for(Edge edge : graph.getAdjacentNodes(currentNode.node)){

               Integer newDistance=currentNode.distanceFromSource+edge.getWeight();

               if(newDistance < distances.get(edge.getDestination())){

                   distances.put(edge.getDestination(),newDistance);

                   //update the priority queue with the new distance.
                   //This is not a standard implementation of dijkstra's algorithm.
                   //In a standard implementation we would have to rebuild the entire queue.
                   //However since we are using a priority queue we can just update the existing element.
                   priorityQueue.remove(new Node(edge.getDestination(),distances.get(edge.getDestination())));
                   priorityQueue.add(new Node(edge.getDestination(),distances.get(edge.getDestination())));
               }


           }



       }



       List<Node> nodes=new ArrayList<>();
       for(Integer node : graph.adjacencyList.keySet()){
           nodes.add(new Node(node,distances.get(node)));
       }
return nodes;


}

